import type { CustomDesign } from './types'

const make = (
  index: number,
  category: string,
  name: string,
  description: string,
  html: string,
  css: string,
  tags: string[],
  js?: string,
): CustomDesign => ({
  id: `next-${String(index).padStart(3, '0')}-${name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`,
  name,
  category,
  description,
  html,
  css,
  js,
  tags,
  source: 'seed',
})

const out: CustomDesign[] = []
let n = 1

const add = (category: string, name: string, description: string, html: string, css: string, tags: string[], js?: string) => {
  out.push(make(n++, category, name, description, html, css, tags, js))
}

// 3D Objects
add('3D Objects','Vault Door','A miniature safe door that unlocks and rotates open in perspective.',`<button class="nx-vault"><span class="nx-wheel">✣</span><b>LOCKED</b></button>`,`.nx-vault{position:relative;width:170px;height:170px;border:10px solid #2a2e38;border-radius:26px;background:radial-gradient(circle,#282d37,#0d1016 68%);box-shadow:inset 0 0 0 5px #090b10,inset 0 0 35px #000,0 24px 40px #0008;perspective:800px;cursor:pointer}.nx-vault:before{content:"";position:absolute;inset:11px;border:3px solid #555e6e;border-radius:18px;transform-origin:left;transition:transform .7s cubic-bezier(.2,.8,.2,1),filter .4s;background:linear-gradient(145deg,#343a46,#151922);box-shadow:inset 0 2px #fff2}.nx-vault:hover:before{transform:rotateY(-58deg);filter:brightness(1.25)}.nx-wheel{position:absolute;inset:0;display:grid;place-items:center;font-size:58px;color:#9ba4b4;z-index:2;transition:transform .7s}.nx-vault:hover .nx-wheel{transform:rotate(230deg) translateX(-8px)}.nx-vault b{position:absolute;bottom:12px;left:0;right:0;font:900 9px Inter;color:#7d8797;letter-spacing:.2em;z-index:3}`,['3d','vault','mechanical','door'])
add('3D Objects','Planetarium','A glass planet with multiple orbital rings and a tiny moon.',`<div class="nx-planet"><span></span><i></i><i></i><i></i></div>`,`.nx-planet{position:relative;width:150px;height:150px;display:grid;place-items:center;perspective:600px}.nx-planet span{width:72px;height:72px;border-radius:50%;background:radial-gradient(circle at 35% 25%,#fff 0 3%,#7dd3fc 12%,#2563eb 45%,#0b1635 70%);box-shadow:inset -14px -15px 25px #0007,0 0 35px #38bdf844;animation:nx-float 3s ease-in-out infinite}.nx-planet i{position:absolute;inset:18px;border:1px solid #ffffff44;border-radius:50%;transform:rotateX(68deg);animation:nx-spin 4s linear infinite}.nx-planet i:nth-of-type(2){inset:8px;transform:rotateY(64deg);animation-duration:5s}.nx-planet i:nth-of-type(3){inset:28px;transform:rotateX(72deg) rotateZ(50deg);animation-duration:2.8s}.nx-planet i:after{content:"";position:absolute;width:8px;height:8px;border-radius:50%;background:#e2e8f0;left:50%;top:-4px;box-shadow:0 0 10px #fff}@keyframes nx-spin{to{rotate:360deg}}@keyframes nx-float{50%{transform:translateY(-8px) rotate(-5deg)}}`,['planet','orbit','3d','space'])
add('3D Objects','Drawer Stack','Three physical drawers slide outward one after another.',`<div class="nx-drawers"><button>01</button><button>02</button><button>03</button></div>`,`.nx-drawers{width:180px;perspective:700px;transform:rotateX(6deg) rotateY(-10deg);transform-style:preserve-3d}.nx-drawers button{display:block;width:100%;height:50px;margin:5px 0;border:1px solid #ffffff18;border-radius:10px;background:linear-gradient(#2c313b,#171a21);color:#b8c0ce;font:900 11px Inter;box-shadow:inset 0 2px #fff2,0 10px 18px #0006;transition:transform .45s cubic-bezier(.2,.9,.2,1.2)}.nx-drawers button:nth-child(2){transition-delay:.05s}.nx-drawers button:nth-child(3){transition-delay:.1s}.nx-drawers:hover button:nth-child(1){transform:translateZ(18px) translateX(26px)}.nx-drawers:hover button:nth-child(2){transform:translateZ(36px) translateX(45px)}.nx-drawers:hover button:nth-child(3){transform:translateZ(54px) translateX(62px)}`,['drawer','stack','3d','depth'])
add('3D Objects','Crystal Core','A faceted crystal rotates with changing spectral light.',`<div class="nx-crystal"><i></i></div>`,`.nx-crystal{width:125px;height:125px;perspective:700px;display:grid;place-items:center}.nx-crystal i{display:block;width:78px;height:96px;clip-path:polygon(50% 0,88% 22%,100% 70%,50% 100%,0 70%,12% 22%);background:linear-gradient(145deg,#ffffffaa,#67e8f9 22%,#8b5cf6 55%,#f472b6 78%,#ffffff88);box-shadow:0 25px 50px #6d5cff55;filter:drop-shadow(0 0 18px #67e8f955);animation:nx-crystal 5s ease-in-out infinite;transform-style:preserve-3d}@keyframes nx-crystal{0%,100%{transform:rotateY(-25deg) rotateX(8deg) translateY(0);filter:hue-rotate(0deg) drop-shadow(0 0 18px #67e8f955)}50%{transform:rotateY(205deg) rotateX(-7deg) translateY(-12px);filter:hue-rotate(80deg) drop-shadow(0 0 28px #f472b655)}}`,['crystal','3d','spectral','object'])
add('3D Objects','Mini Satellite','A tiny satellite spins around its own axis with folding panels.',`<div class="nx-sat"><span></span><i></i><i></i><b>●</b></div>`,`.nx-sat{position:relative;width:170px;height:100px;display:grid;place-items:center;perspective:700px;animation:nx-sat-float 4s ease-in-out infinite}.nx-sat span{width:48px;height:48px;border-radius:12px;background:linear-gradient(145deg,#d7dde8,#697386);box-shadow:inset 0 2px #fff,0 15px 25px #0006}.nx-sat i{position:absolute;width:58px;height:34px;background:repeating-linear-gradient(90deg,#2255ad 0 8px,#183a75 8px 10px);border:1px solid #8ab4ff66;top:33px}.nx-sat i:first-of-type{left:10px;transform:rotateY(-20deg)}.nx-sat i:nth-of-type(2){right:10px;transform:rotateY(20deg)}.nx-sat b{position:absolute;color:#22d3ee;transform:translateZ(25px);text-shadow:0 0 14px #22d3ee}@keyframes nx-sat-float{50%{transform:translateY(-10px) rotateZ(3deg) rotateY(14deg)}}`,['satellite','space','3d','floating'])
add('3D Objects','Portal Ring','A metallic ring opens a luminous portal when hovered.',`<div class="nx-portal-ring"><i></i><b>ENTER</b></div>`,`.nx-portal-ring{position:relative;width:145px;height:145px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(#323743,#80889a,#242833,#959dad,#323743);box-shadow:0 25px 45px #0008,inset 0 0 18px #000;transition:transform .4s}.nx-portal-ring:before{content:"";position:absolute;inset:14px;border-radius:50%;background:#05070b;box-shadow:inset 0 0 18px #000}.nx-portal-ring i{position:absolute;inset:24px;border-radius:50%;background:conic-gradient(#22d3ee,#756cff,#f472b6,#22d3ee);filter:blur(7px);opacity:.2;transition:.45s;animation:nx-ring 3s linear infinite}.nx-portal-ring b{position:relative;color:#768092;font:900 9px Inter;letter-spacing:.15em}.nx-portal-ring:hover{transform:scale(1.05) rotateX(10deg)}.nx-portal-ring:hover i{opacity:1;transform:scale(1.12)}.nx-portal-ring:hover b{color:white;text-shadow:0 0 12px #22d3ee}@keyframes nx-ring{to{rotate:360deg}}`,['portal','ring','3d','glow'])
add('3D Objects','Floating Dice','A glass dice slowly tumbles in pseudo-3D.',`<div class="nx-dice"><span>● ●</span><b>●</b><i>● ● ●</i></div>`,`.nx-dice{position:relative;width:92px;height:92px;border-radius:20px;background:linear-gradient(145deg,#ffffff20,#ffffff08);border:1px solid #ffffff30;backdrop-filter:blur(14px);box-shadow:inset 0 1px #fff5,0 25px 45px #0007;transform-style:preserve-3d;animation:nx-dice 5s ease-in-out infinite}.nx-dice span,.nx-dice b,.nx-dice i{position:absolute;color:#d8d5ff;font-style:normal;font:900 14px Inter;text-shadow:0 0 10px #756cff}.nx-dice span{left:16px;top:16px}.nx-dice b{right:18px;bottom:18px}.nx-dice i{left:28px;top:40px;transform:rotate(45deg)}@keyframes nx-dice{0%,100%{transform:rotateX(15deg) rotateY(-20deg) translateY(0)}50%{transform:rotateX(195deg) rotateY(160deg) translateY(-12px)}}`,['dice','glass','3d','tumble'])
add('3D Objects','Hover Drone','A little drone hovers and tilts toward the pointer.',`<div class="nx-drone"><i></i><i></i><span>◆</span></div>`,`.nx-drone{position:relative;width:150px;height:90px;display:grid;place-items:center;transition:transform .08s;filter:drop-shadow(0 18px 12px #0008)}.nx-drone span{width:58px;height:38px;border-radius:20px;background:linear-gradient(145deg,#3f4654,#171a20);display:grid;place-items:center;color:#22d3ee;box-shadow:inset 0 2px #fff2}.nx-drone i{position:absolute;width:60px;height:4px;background:#505967;top:43px}.nx-drone i:first-child{left:8px;transform:rotate(16deg)}.nx-drone i:nth-child(2){right:8px;transform:rotate(-16deg)}.nx-drone:before,.nx-drone:after{content:"";position:absolute;width:34px;height:34px;border:2px solid #8892a0;border-radius:50%;top:26px;animation:nx-prop .35s linear infinite}.nx-drone:before{left:2px}.nx-drone:after{right:2px}@keyframes nx-prop{to{rotate:360deg}}`,['drone','hover','pointer','3d'],`const d=document.querySelector('.nx-drone');document.addEventListener('pointermove',e=>{const r=d.getBoundingClientRect(),x=(e.clientX-(r.left+r.width/2))/r.width,y=(e.clientY-(r.top+r.height/2))/r.height;d.style.transform='translateY(-5px) rotateX('+(-y*12)+'deg) rotateY('+(x*14)+'deg)'})`)
add('3D Objects','Capsule Pod','A sci-fi capsule splits open and reveals a glowing core.',`<button class="nx-pod"><span></span><i></i><b>CORE</b></button>`,`.nx-pod{position:relative;width:160px;height:68px;border:0;background:none;cursor:pointer}.nx-pod span,.nx-pod i{position:absolute;top:0;width:52%;height:100%;background:linear-gradient(145deg,#3c424f,#141820);border:1px solid #ffffff20;box-shadow:inset 0 2px #fff2;transition:.45s cubic-bezier(.2,.9,.2,1.2)}.nx-pod span{left:0;border-radius:34px 4px 4px 34px}.nx-pod i{right:0;border-radius:4px 34px 34px 4px}.nx-pod b{position:absolute;inset:0;display:grid;place-items:center;color:#22d3ee;font:900 10px Inter;letter-spacing:.18em;text-shadow:0 0 12px #22d3ee}.nx-pod:hover span{transform:translateX(-28px) rotateY(28deg)}.nx-pod:hover i{transform:translateX(28px) rotateY(-28deg)}.nx-pod:hover b{font-size:13px;filter:drop-shadow(0 0 8px #22d3ee)}`,['capsule','pod','sci-fi','split'])
add('3D Objects','Mini Elevator','A tiny elevator door slides open and the cabin glows.',`<div class="nx-elevator"><i></i><i></i><span>08</span></div>`,`.nx-elevator{position:relative;width:120px;height:150px;border:8px solid #2b303a;border-radius:14px;background:radial-gradient(circle,#22d3ee33,#05070a 60%);overflow:hidden;box-shadow:0 22px 35px #0008,inset 0 0 25px #22d3ee33}.nx-elevator i{position:absolute;top:0;bottom:0;width:50%;background:linear-gradient(90deg,#2c313b,#15181f);transition:.55s cubic-bezier(.2,.8,.2,1)}.nx-elevator i:first-child{left:0;border-right:1px solid #000}.nx-elevator i:nth-child(2){right:0;border-left:1px solid #555}.nx-elevator:hover i:first-child{transform:translateX(-95%)}.nx-elevator:hover i:nth-child(2){transform:translateX(95%)}.nx-elevator span{position:absolute;top:8px;right:8px;color:#2dd4bf;font:900 8px monospace;text-shadow:0 0 8px #2dd4bf}`,['elevator','door','sci-fi','3d'])

// Mechanical Controls
add('Mechanical Controls','Safety Cover Switch','A guarded switch with a hinged transparent safety cover.',`<label class="nx-safety"><input type="checkbox"><span class="nx-cover"></span><i></i><b>ARM</b></label>`,`.nx-safety{position:relative;width:90px;height:120px;display:block;background:#1a1d23;border:2px solid #3a3f49;border-radius:18px;box-shadow:inset 0 0 18px #000,0 18px 30px #0007;cursor:pointer;perspective:500px}.nx-safety input{position:absolute;opacity:0}.nx-cover{position:absolute;inset:8px;border-radius:12px;background:#ff465522;border:1px solid #ff7a8566;backdrop-filter:blur(2px);transform-origin:top;transition:.45s;z-index:3}.nx-safety:hover .nx-cover{transform:rotateX(72deg)}.nx-safety i{position:absolute;width:24px;height:54px;left:31px;top:34px;border-radius:12px;background:linear-gradient(#d7dbe2,#555d68);transform-origin:50% 85%;transform:rotate(-25deg);transition:.35s cubic-bezier(.2,1.4,.3,1)}.nx-safety input:checked~i{transform:rotate(25deg)}.nx-safety b{position:absolute;bottom:8px;left:0;right:0;text-align:center;color:#727b89;font:900 8px Inter;letter-spacing:.12em}`,['mechanical','switch','safety','hinge'])
add('Mechanical Controls','Rotary Dial','A heavy rotary dial with tactile detents.',`<div class="nx-dial"><button></button><span>0</span><span>1</span><span>2</span><span>3</span></div>`,`.nx-dial{position:relative;width:130px;height:130px;border-radius:50%;background:radial-gradient(circle,#232832 0 48%,#0b0d11 49% 60%,#343b46 61% 64%,#121419 65%);box-shadow:inset 0 0 25px #000,0 20px 35px #0008}.nx-dial button{position:absolute;left:50%;top:50%;width:58px;height:58px;border:0;border-radius:50%;background:linear-gradient(145deg,#4b5360,#191d23);box-shadow:inset 0 3px #fff2,0 8px 15px #0008;transform:translate(-50%,-50%) rotate(var(--r,0deg));cursor:grab;transition:transform .2s}.nx-dial button:after{content:"";position:absolute;width:5px;height:16px;border-radius:5px;background:#22d3ee;top:7px;left:27px;box-shadow:0 0 8px #22d3ee}.nx-dial span{position:absolute;color:#667080;font:900 8px Inter}.nx-dial span:nth-of-type(1){left:62px;top:8px}.nx-dial span:nth-of-type(2){right:15px;top:58px}.nx-dial span:nth-of-type(3){left:62px;bottom:8px}.nx-dial span:nth-of-type(4){left:15px;top:58px}`,['dial','rotary','mechanical','control'],`const b=document.querySelector('.nx-dial button');let r=0;b.addEventListener('click',()=>{r=(r+90)%360;b.style.setProperty('--r',r+'deg')})`)
add('Mechanical Controls','Push Plunger','A chunky industrial plunger with full physical travel.',`<button class="nx-plunger"><span>PUSH</span></button>`,`.nx-plunger{position:relative;width:120px;height:74px;border:0;border-radius:26px;background:#252932;box-shadow:0 11px 0 #08090c,0 20px 28px #0008,inset 0 2px #fff2;cursor:pointer;transition:.12s}.nx-plunger span{position:absolute;inset:10px;border-radius:19px;display:grid;place-items:center;background:radial-gradient(circle at 50% 20%,#ff8a9c,#df2647 65%,#8b0f28);color:#fff;font:1000 12px Inter;letter-spacing:.12em;box-shadow:inset 0 5px 5px #fff3,inset 0 -8px 10px #6005,0 0 18px #fb718533}.nx-plunger:active{transform:translateY(9px);box-shadow:0 2px 0 #08090c,0 5px 10px #0006}`,['button','plunger','mechanical','physical'])
add('Mechanical Controls','Lever Gate','A metal lever slides through a slot with a glowing state indicator.',`<label class="nx-lever"><input type="checkbox"><span></span><i></i><b></b></label>`,`.nx-lever{position:relative;width:150px;height:70px;border-radius:18px;background:#12151b;border:1px solid #ffffff15;box-shadow:inset 0 0 20px #000,0 16px 26px #0007;display:block;cursor:pointer}.nx-lever input{position:absolute;opacity:0}.nx-lever span{position:absolute;left:24px;right:24px;top:30px;height:10px;border-radius:8px;background:#050609;box-shadow:inset 0 2px 5px #000}.nx-lever i{position:absolute;width:16px;height:50px;left:34px;top:10px;border-radius:9px;background:linear-gradient(90deg,#9aa3b0,#4c535e);transform:rotate(-20deg);transform-origin:50% 80%;transition:.38s cubic-bezier(.2,1.4,.3,1)}.nx-lever input:checked~i{left:100px;transform:rotate(20deg)}.nx-lever b{position:absolute;right:14px;top:12px;width:8px;height:8px;border-radius:50%;background:#fb7185;box-shadow:0 0 12px #fb7185}.nx-lever input:checked~b{background:#2dd4bf;box-shadow:0 0 14px #2dd4bf}`,['lever','mechanical','switch','industrial'])
add('Mechanical Controls','Breaker Switch','A circuit breaker snaps between two hard states.',`<label class="nx-breaker"><input type="checkbox"><span><b>OFF</b><i>ON</i></span></label>`,`.nx-breaker{display:block;width:76px;height:120px;border-radius:18px;background:#d8dbe0;padding:10px;box-shadow:0 18px 30px #0007,inset 0 2px #fff;cursor:pointer}.nx-breaker input{position:absolute;opacity:0}.nx-breaker span{position:relative;display:block;width:100%;height:100%;border-radius:12px;background:#252932;box-shadow:inset 0 8px 12px #0008}.nx-breaker b,.nx-breaker i{position:absolute;left:9px;right:9px;height:42px;border-radius:8px;display:grid;place-items:center;color:#fff;font:900 9px Inter;transition:.25s}.nx-breaker b{top:9px;background:#374151}.nx-breaker i{bottom:9px;background:#16a34a;font-style:normal;transform:translateY(38px);opacity:.2}.nx-breaker input:checked+span b{transform:translateY(-38px);opacity:.2}.nx-breaker input:checked+span i{transform:translateY(0);opacity:1}`,['breaker','switch','mechanical','power'])
add('Mechanical Controls','Flip Guard Button','A red action button protected by a flip-up metal guard.',`<div class="nx-guard"><button>FIRE</button><span></span></div>`,`.nx-guard{position:relative;width:130px;height:90px;perspective:500px}.nx-guard button{position:absolute;left:25px;top:20px;width:80px;height:56px;border:0;border-radius:15px;background:linear-gradient(#ff617b,#a60e2d);color:#fff;font:1000 11px Inter;box-shadow:inset 0 4px #fff3,0 10px 0 #5d091c,0 18px 20px #0007}.nx-guard span{position:absolute;inset:4px 12px 8px;border:3px solid #8b93a0;border-radius:15px 15px 5px 5px;transform-origin:top;transition:.45s;background:#ffffff0b;backdrop-filter:blur(2px)}.nx-guard:hover span{transform:rotateX(78deg)}`,['guard','mechanical','button','hinge'])
add('Mechanical Controls','Mechanical Slider','A thick slider with a weighted metal thumb.',`<input class="nx-slider" type="range" min="0" max="100" value="55">`,`.nx-slider{appearance:none;width:200px;height:16px;border-radius:10px;background:linear-gradient(#07090d,#242832);box-shadow:inset 0 4px 8px #000,0 2px #ffffff10;outline:none}.nx-slider::-webkit-slider-thumb{appearance:none;width:42px;height:42px;border-radius:14px;background:linear-gradient(145deg,#8993a2,#343a44);border:1px solid #ffffff35;box-shadow:inset 0 3px #fff3,0 9px 16px #0008;cursor:grab}.nx-slider::-moz-range-thumb{width:42px;height:42px;border-radius:14px;background:linear-gradient(145deg,#8993a2,#343a44);border:1px solid #ffffff35;box-shadow:inset 0 3px #fff3,0 9px 16px #0008}`,['slider','mechanical','control','metal'])
add('Mechanical Controls','Key Ignition','A key rotates from standby to active and lights the panel.',`<button class="nx-key"><span>◆</span><b>IGNITION</b></button>`,`.nx-key{position:relative;width:130px;height:130px;border-radius:50%;border:10px solid #343a45;background:radial-gradient(circle,#0d1015 0 45%,#1f242c 46% 58%,#080a0e 59%);box-shadow:inset 0 0 20px #000,0 20px 34px #0008;cursor:pointer}.nx-key span{position:absolute;left:50%;top:50%;width:18px;height:68px;background:linear-gradient(90deg,#b7bec8,#555d68);clip-path:polygon(30% 0,70% 0,100% 68%,62% 100%,38% 100%,0 68%);transform-origin:50% 76%;transform:translate(-50%,-66%) rotate(-38deg);transition:.5s cubic-bezier(.2,1.2,.2,1)}.nx-key b{position:absolute;bottom:12px;left:0;right:0;color:#667080;font:900 8px Inter;letter-spacing:.12em}.nx-key:focus span{transform:translate(-50%,-66%) rotate(38deg)}.nx-key:focus{box-shadow:inset 0 0 20px #000,0 0 28px #2dd4bf44}.nx-key:focus b{color:#2dd4bf}`,['key','ignition','mechanical','rotate'])
add('Mechanical Controls','Emergency Mushroom','A huge emergency stop button with twist reset.',`<button class="nx-stop">STOP</button>`,`.nx-stop{width:130px;height:78px;border:0;border-radius:50%;background:#24272d;color:#fff;font:1000 14px Inter;letter-spacing:.12em;box-shadow:0 12px 0 #07080a,0 22px 30px #0008,inset 0 4px #fff2;position:relative;cursor:pointer}.nx-stop:before{content:"";position:absolute;left:19px;right:19px;top:8px;bottom:15px;border-radius:50%;background:radial-gradient(circle at 50% 25%,#ff627c,#c81033 60%,#71071d);box-shadow:inset 0 6px 8px #fff3}.nx-stop{isolation:isolate}.nx-stop::after{content:"STOP";position:absolute;inset:0;display:grid;place-items:center;z-index:2}.nx-stop:active{transform:translateY(9px) rotate(4deg);box-shadow:0 3px 0 #07080a,0 7px 12px #0008}`,['emergency','button','physical','mechanical'])
add('Mechanical Controls','Dual Paddle','Two weighted paddles flip like cockpit switches.',`<div class="nx-paddles"><button>L</button><button>R</button></div>`,`.nx-paddles{display:flex;gap:18px;padding:16px 20px;border-radius:20px;background:#15181e;border:1px solid #ffffff15;box-shadow:inset 0 0 18px #000,0 18px 30px #0007;perspective:500px}.nx-paddles button{width:48px;height:72px;border:0;border-radius:12px;background:linear-gradient(145deg,#5c6471,#232831);color:#c7cdd7;font:900 10px Inter;box-shadow:inset 0 3px #fff2,0 8px 14px #0008;transform-origin:bottom;transition:.2s;cursor:pointer}.nx-paddles button:active{transform:rotateX(-28deg) translateY(5px)}`,['paddle','mechanical','cockpit','control'])

// Mini Games
add('Mini Games','Mini Pong','A tiny autonomous pong game inside a glass panel.',`<div class="nx-pong"><i></i><i></i><b></b></div>`,`.nx-pong{position:relative;width:220px;height:135px;border:1px solid #ffffff20;border-radius:18px;background:#05070b;overflow:hidden;box-shadow:inset 0 0 25px #22d3ee12,0 18px 34px #0008}.nx-pong i{position:absolute;width:6px;height:36px;background:#e5f9ff;top:48px;box-shadow:0 0 8px #22d3ee}.nx-pong i:first-child{left:12px;animation:nx-paddle-a 2s ease-in-out infinite}.nx-pong i:nth-child(2){right:12px;animation:nx-paddle-b 2.2s ease-in-out infinite}.nx-pong b{position:absolute;width:9px;height:9px;border-radius:50%;background:#fff;left:50%;top:50%;box-shadow:0 0 10px #fff;animation:nx-ball 2s linear infinite}@keyframes nx-paddle-a{50%{transform:translateY(42px)}}@keyframes nx-paddle-b{50%{transform:translateY(-35px)}}@keyframes nx-ball{0%{transform:translate(-85px,-35px)}25%{transform:translate(82px,28px)}50%{transform:translate(-10px,52px)}75%{transform:translate(-84px,5px)}100%{transform:translate(-85px,-35px)}}`,['game','pong','mini','animated'])
add('Mini Games','Slot Machine','Three reels spin and snap into place on click.',`<button class="nx-slot"><span>7</span><span>★</span><span>7</span><b>PULL</b></button>`,`.nx-slot{position:relative;width:180px;height:110px;border:6px solid #eab308;border-radius:22px;background:linear-gradient(#7c2d12,#3f1308);display:flex;gap:7px;justify-content:center;align-items:center;padding-bottom:24px;box-shadow:0 20px 35px #0008,inset 0 0 18px #000;cursor:pointer}.nx-slot span{width:42px;height:52px;border-radius:7px;background:#fff;color:#a30d23;display:grid;place-items:center;font:1000 25px serif;box-shadow:inset 0 0 8px #0003;transition:.25s}.nx-slot b{position:absolute;bottom:6px;color:#ffd56b;font:900 9px Inter;letter-spacing:.16em}.nx-slot:focus span{animation:nx-reel .7s ease-out}.nx-slot:focus span:nth-child(2){animation-delay:.12s}.nx-slot:focus span:nth-child(3){animation-delay:.24s}@keyframes nx-reel{0%{transform:rotateX(0)}70%{transform:rotateX(1080deg)}100%{transform:rotateX(1440deg)}}`,['game','slot','reel','3d'])
add('Mini Games','Pinball Bumper','A glowing pinball bumper launches a ball when clicked.',`<button class="nx-pinball"><i></i><b>HIT</b></button>`,`.nx-pinball{position:relative;width:160px;height:120px;border:1px solid #ffffff18;border-radius:28px;background:radial-gradient(circle,#141826,#080a0f 70%);overflow:hidden;cursor:pointer}.nx-pinball:before{content:"";position:absolute;width:62px;height:62px;border-radius:50%;left:49px;top:29px;background:radial-gradient(circle,#fff 0 8%,#f472b6 20%,#7c3aed 65%);box-shadow:0 0 25px #a855f7}.nx-pinball i{position:absolute;width:12px;height:12px;border-radius:50%;background:#fff;left:74px;top:54px;box-shadow:0 0 10px #fff}.nx-pinball b{position:absolute;bottom:9px;left:0;right:0;color:#6f7785;font:900 8px Inter;letter-spacing:.15em}.nx-pinball:focus i{animation:nx-pin .65s cubic-bezier(.2,.9,.2,1)}@keyframes nx-pin{0%{transform:translate(0,0)}30%{transform:translate(58px,-38px)}60%{transform:translate(-42px,-15px)}100%{transform:translate(0,0)}}`,['game','pinball','physics','bounce'])
add('Mini Games','Memory Lights','Four pads flash in a repeating memory-game sequence.',`<div class="nx-memory"><i></i><i></i><i></i><i></i></div>`,`.nx-memory{display:grid;grid-template-columns:repeat(2,58px);gap:8px;padding:12px;border-radius:22px;background:#0d1015;box-shadow:inset 0 0 18px #000,0 18px 28px #0007}.nx-memory i{width:58px;height:58px;border-radius:16px;background:#222731;box-shadow:inset 0 2px #fff1}.nx-memory i:nth-child(1){animation:nx-memory 2.4s infinite 0s}.nx-memory i:nth-child(2){animation:nx-memory 2.4s infinite .35s}.nx-memory i:nth-child(3){animation:nx-memory 2.4s infinite .7s}.nx-memory i:nth-child(4){animation:nx-memory 2.4s infinite 1.05s}@keyframes nx-memory{0%,15%,100%{background:#222731;box-shadow:inset 0 2px #fff1}6%{background:#756cff;box-shadow:0 0 22px #756cff}}`,['game','memory','lights','sequence'])
add('Mini Games','Breakout Brick','A mini breakout scene with moving ball and paddle.',`<div class="nx-breakout"><div></div><i></i><b></b></div>`,`.nx-breakout{position:relative;width:220px;height:140px;border-radius:18px;background:#06080c;border:1px solid #ffffff15;overflow:hidden}.nx-breakout div{height:38px;margin:10px;background:repeating-linear-gradient(90deg,#756cff 0 30px,#06080c 30px 34px);box-shadow:0 10px 0 #22d3ee,0 20px 0 #f472b6;opacity:.8}.nx-breakout i{position:absolute;width:48px;height:6px;border-radius:8px;background:#fff;left:86px;bottom:9px;animation:nx-breakout-p 1.8s ease-in-out infinite}.nx-breakout b{position:absolute;width:8px;height:8px;border-radius:50%;background:#fff;left:105px;bottom:22px;animation:nx-breakout-b 1.8s linear infinite}@keyframes nx-breakout-p{50%{transform:translateX(60px)}}@keyframes nx-breakout-b{0%{transform:translate(0,0)}25%{transform:translate(70px,-85px)}50%{transform:translate(55px,-5px)}75%{transform:translate(-75px,-65px)}100%{transform:translate(0,0)}}`,['game','breakout','arcade','animated'])
add('Mini Games','Reaction Tap','A target appears at random positions for a reaction-speed tap.',`<button class="nx-reaction"><i></i><span>TAP</span></button>`,`.nx-reaction{position:relative;width:220px;height:130px;border:1px solid #ffffff18;border-radius:20px;background:#090b10;overflow:hidden;cursor:crosshair}.nx-reaction i{position:absolute;width:30px;height:30px;border-radius:50%;background:radial-gradient(circle,#fff 0 10%,#2dd4bf 22%,#0f766e 66%);box-shadow:0 0 18px #2dd4bf;animation:nx-target 3s steps(1) infinite}.nx-reaction span{position:absolute;left:12px;bottom:10px;color:#596273;font:900 8px Inter;letter-spacing:.15em}@keyframes nx-target{0%{left:25px;top:20px}20%{left:160px;top:70px}40%{left:110px;top:15px}60%{left:40px;top:80px}80%{left:145px;top:38px}}`,['game','reaction','target','tap'])
add('Mini Games','Gravity Box','Several balls bounce with fake gravity inside a box.',`<div class="nx-gravity"><i></i><i></i><i></i></div>`,`.nx-gravity{position:relative;width:220px;height:135px;border:1px solid #ffffff18;border-radius:20px;background:linear-gradient(#0e1118,#080a0e);overflow:hidden}.nx-gravity i{position:absolute;width:20px;height:20px;border-radius:50%;bottom:10px;background:#756cff;box-shadow:0 0 14px #756cff}.nx-gravity i:nth-child(1){left:35px;animation:nx-g 1.15s cubic-bezier(.2,.8,.2,1) infinite}.nx-gravity i:nth-child(2){left:100px;background:#22d3ee;box-shadow:0 0 14px #22d3ee;animation:nx-g 1.45s cubic-bezier(.2,.8,.2,1) infinite .2s}.nx-gravity i:nth-child(3){left:165px;background:#f472b6;box-shadow:0 0 14px #f472b6;animation:nx-g 1.3s cubic-bezier(.2,.8,.2,1) infinite .4s}@keyframes nx-g{0%,100%{transform:translateY(0) scaleY(.85)}45%{transform:translateY(-92px) scaleY(1.05)}70%{transform:translateY(-32px)}}`,['game','gravity','balls','physics'])
add('Mini Games','Tilt Maze','A tiny ball rolls toward the cursor inside a maze board.',`<div class="nx-maze"><i></i><b></b><span></span></div>`,`.nx-maze{position:relative;width:210px;height:135px;border-radius:18px;background:#12151c;border:1px solid #ffffff18;box-shadow:0 20px 35px #0008;overflow:hidden;transition:transform .08s}.nx-maze:before{content:"";position:absolute;inset:15px;background:linear-gradient(90deg,transparent 45%,#434956 46% 51%,transparent 52%),linear-gradient(transparent 45%,#434956 46% 51%,transparent 52%);border:2px solid #434956}.nx-maze i{position:absolute;width:17px;height:17px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff,#9ba5b4 30%,#333b46);left:96px;top:59px;z-index:2;transition:transform .12s}.nx-maze b,.nx-maze span{position:absolute;width:25px;height:25px;border:2px solid #2dd4bf;z-index:1}.nx-maze b{left:18px;top:18px}.nx-maze span{right:18px;bottom:18px}`,['game','maze','tilt','pointer'],`const m=document.querySelector('.nx-maze'),ball=m.querySelector('i');m.addEventListener('pointermove',e=>{const r=m.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/r.width,y=(e.clientY-r.top-r.height/2)/r.height;m.style.transform='perspective(600px) rotateX('+(-y*10)+'deg) rotateY('+(x*12)+'deg)';ball.style.transform='translate('+(x*55)+'px,'+(y*38)+'px)'})`)
add('Mini Games','Whack Dot','A glowing dot pops up in different holes.',`<div class="nx-whack"><i></i><i></i><i></i><i></i><b>●</b></div>`,`.nx-whack{position:relative;width:200px;height:120px;display:grid;grid-template-columns:repeat(2,1fr);gap:12px;padding:18px;border-radius:20px;background:#12151b}.nx-whack i{border-radius:50%;background:#050609;box-shadow:inset 0 7px 12px #000}.nx-whack b{position:absolute;color:#f472b6;font-size:34px;text-shadow:0 0 18px #f472b6;animation:nx-whack 3s steps(1) infinite}@keyframes nx-whack{0%{left:42px;top:20px}25%{left:132px;top:20px}50%{left:42px;top:68px}75%{left:132px;top:68px}}`,['game','whack','dot','animated'])
add('Mini Games','Mini Racer','A tiny car loops around a neon track.',`<div class="nx-racer"><span>▰</span></div>`,`.nx-racer{position:relative;width:220px;height:130px;border-radius:24px;background:#080a0f;border:1px solid #ffffff16;overflow:hidden}.nx-racer:before{content:"";position:absolute;inset:24px;border:3px solid #343b48;border-radius:45px;box-shadow:0 0 18px #22d3ee22,inset 0 0 12px #756cff22}.nx-racer span{position:absolute;color:#f59e0b;font-size:18px;left:30px;top:54px;filter:drop-shadow(0 0 7px #f59e0b);offset-path:path('M 0 20 C 30 -20 120 -20 150 20 C 180 60 120 75 75 72 C 30 75 -20 60 0 20');animation:nx-race 4s linear infinite}@keyframes nx-race{to{offset-distance:100%}}`,['game','racer','track','neon'])

// Spatial Windows
add('Spatial Windows','Floating Window','A window floats in depth and tilts toward the pointer.',`<div class="nx-window"><header><i></i><i></i><i></i><b>Spatial</b></header><main>HELLO<br><strong>DEPTH</strong></main></div>`,`.nx-window{width:250px;height:160px;border:1px solid #ffffff22;border-radius:20px;background:#11151dcc;backdrop-filter:blur(18px);box-shadow:0 30px 65px #0008,inset 0 1px #fff2;transform-style:preserve-3d;transition:transform .08s}.nx-window header{height:35px;border-bottom:1px solid #ffffff12;display:flex;gap:6px;align-items:center;padding:0 10px}.nx-window header i{width:7px;height:7px;border-radius:50%;background:#fb7185}.nx-window header i:nth-child(2){background:#fbbf24}.nx-window header i:nth-child(3){background:#2dd4bf}.nx-window header b{margin-left:auto;color:#626b7b;font:700 8px Inter}.nx-window main{height:125px;display:grid;place-items:center;text-align:center;color:#748094;font:900 12px Inter;letter-spacing:.1em}.nx-window strong{font-size:28px;color:#fff;text-shadow:0 0 22px #756cff}`,['window','spatial','glass','tilt'],`const w=document.querySelector('.nx-window');document.addEventListener('pointermove',e=>{const r=w.getBoundingClientRect(),x=(e.clientX-(r.left+r.width/2))/r.width,y=(e.clientY-(r.top+r.height/2))/r.height;w.style.transform='perspective(800px) rotateX('+(-y*12)+'deg) rotateY('+(x*14)+'deg) translateZ(12px)'})`)
add('Spatial Windows','Layered Panels','Three translucent panels separate in Z-space on hover.',`<div class="nx-layers"><i></i><i></i><i></i><b>STACK</b></div>`,`.nx-layers{position:relative;width:220px;height:145px;perspective:700px;transform-style:preserve-3d}.nx-layers i{position:absolute;inset:15px;border-radius:18px;border:1px solid #ffffff22;background:linear-gradient(145deg,#ffffff10,#ffffff04);backdrop-filter:blur(10px);transition:.5s}.nx-layers i:nth-child(1){transform:translateZ(0) rotate(-3deg)}.nx-layers i:nth-child(2){transform:translateZ(10px) rotate(2deg)}.nx-layers i:nth-child(3){transform:translateZ(20px);background:#756cff13}.nx-layers:hover i:nth-child(1){transform:translate3d(-28px,18px,-20px) rotate(-7deg)}.nx-layers:hover i:nth-child(2){transform:translate3d(0,0,10px) rotate(2deg)}.nx-layers:hover i:nth-child(3){transform:translate3d(30px,-20px,40px) rotate(6deg)}.nx-layers b{position:absolute;inset:0;display:grid;place-items:center;color:#fff;font:900 13px Inter;z-index:4;text-shadow:0 0 16px #756cff}`,['window','layers','depth','glass'])
add('Spatial Windows','Docked Panel','A side panel peels away from the wall like a physical sheet.',`<div class="nx-docked"><aside>TOOLS</aside><main>WORKSPACE</main></div>`,`.nx-docked{display:flex;width:250px;height:150px;border-radius:18px;background:#0d1016;perspective:700px;box-shadow:0 22px 42px #0008;overflow:visible}.nx-docked aside{width:70px;display:grid;place-items:center;background:#191d25;border-radius:18px 0 0 18px;color:#697384;font:900 9px Inter;letter-spacing:.12em;transform-origin:left;transition:.5s}.nx-docked main{flex:1;display:grid;place-items:center;color:#414959;font:900 11px Inter}.nx-docked:hover aside{transform:rotateY(-48deg) translateZ(18px);background:#756cff;color:white;box-shadow:12px 0 25px #0007}`,['window','panel','hinge','spatial'])
add('Spatial Windows','Portal Window','A window opens into an animated colorful void.',`<div class="nx-portal-win"><span>OPEN SPACE</span></div>`,`.nx-portal-win{position:relative;width:245px;height:150px;border:9px solid #2b3039;border-radius:24px;background:#05060a;overflow:hidden;box-shadow:0 25px 45px #0009,inset 0 0 20px #000}.nx-portal-win:before{content:"";position:absolute;inset:-40%;background:conic-gradient(#22d3ee,#756cff,#f472b6,#2dd4bf,#22d3ee);animation:nx-void 7s linear infinite;filter:blur(25px);opacity:.6}.nx-portal-win:after{content:"";position:absolute;inset:16px;border-radius:50%;background:#05060a;box-shadow:0 0 30px #000 inset}.nx-portal-win span{position:absolute;z-index:3;inset:0;display:grid;place-items:center;color:#fff;font:900 11px Inter;letter-spacing:.15em;text-shadow:0 0 14px #22d3ee}@keyframes nx-void{to{rotate:360deg}}`,['window','portal','void','animated'])
add('Spatial Windows','Pinned Note','A glass sticky note bends slightly when hovered.',`<div class="nx-note"><i></i><b>IDEA</b><span>Make interfaces feel alive.</span></div>`,`.nx-note{position:relative;width:190px;height:150px;border-radius:8px 18px 14px 20px;background:linear-gradient(145deg,#fef3c7dd,#fde68add);color:#5c4016;padding:24px 18px 18px;box-shadow:0 25px 38px #0006;transform:rotate(-2deg);transition:.35s;transform-origin:top}.nx-note i{position:absolute;width:16px;height:16px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff,#ef4444 25%,#991b1b);top:8px;left:87px;box-shadow:0 5px 7px #0004}.nx-note b{display:block;font:1000 14px Inter;margin-bottom:10px}.nx-note span{font:600 10px/1.6 Inter}.nx-note:hover{transform:perspective(600px) rotateX(-8deg) rotateY(5deg) rotate(1deg) translateY(-7px)}`,['note','paper','spatial','bend'])
add('Spatial Windows','Window Stack','A stack of windows fans out like cards.',`<div class="nx-win-stack"><i></i><i></i><i></i></div>`,`.nx-win-stack{position:relative;width:220px;height:150px;perspective:700px}.nx-win-stack i{position:absolute;inset:18px;border-radius:18px;background:linear-gradient(145deg,#1b1f28dd,#0e1118dd);border:1px solid #ffffff18;box-shadow:0 18px 34px #0008;transition:.5s}.nx-win-stack i:nth-child(1){transform:translate(-12px,12px) rotate(-5deg)}.nx-win-stack i:nth-child(2){transform:translate(0,0)}.nx-win-stack i:nth-child(3){transform:translate(12px,-12px) rotate(5deg);background:#756cff18}.nx-win-stack:hover i:nth-child(1){transform:translate(-55px,20px) rotate(-12deg)}.nx-win-stack:hover i:nth-child(2){transform:translate(0,-10px)}.nx-win-stack:hover i:nth-child(3){transform:translate(55px,-28px) rotate(12deg)}`,['window','stack','fan','spatial'])
add('Spatial Windows','Elastic Window','A panel stretches toward the pointer before snapping back.',`<div class="nx-elastic"><b>ELASTIC</b></div>`,`.nx-elastic{width:230px;height:140px;border:1px solid #ffffff20;border-radius:24px;background:linear-gradient(145deg,#161a22,#0c0f15);display:grid;place-items:center;box-shadow:0 22px 42px #0007;transition:transform .12s;border-radius:var(--r1,24px) var(--r2,24px) var(--r3,24px) var(--r4,24px)}.nx-elastic b{color:#fff;font:900 12px Inter;letter-spacing:.15em}`,['window','elastic','pointer','morph'],`const w=document.querySelector('.nx-elastic');w.addEventListener('pointermove',e=>{const r=w.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;w.style.transform='scale('+(1+Math.abs(x-.5)*.05)+','+(1+Math.abs(y-.5)*.05)+') translate('+((x-.5)*8)+'px,'+((y-.5)*8)+'px)';w.style.setProperty('--r1',(16+x*24)+'px');w.style.setProperty('--r3',(16+(1-x)*24)+'px')});w.addEventListener('pointerleave',()=>w.style.transform='')`)
add('Spatial Windows','Depth Carousel','Three windows rotate through a 3D carousel.',`<div class="nx-carousel"><i>A</i><i>B</i><i>C</i></div>`,`.nx-carousel{position:relative;width:240px;height:145px;perspective:800px;transform-style:preserve-3d;animation:nx-car 8s ease-in-out infinite}.nx-carousel i{position:absolute;left:65px;top:25px;width:110px;height:95px;border-radius:16px;background:linear-gradient(145deg,#1d222c,#0d1016);border:1px solid #ffffff18;display:grid;place-items:center;color:#fff;font:1000 24px Inter;box-shadow:0 18px 30px #0008}.nx-carousel i:nth-child(1){transform:rotateY(0deg) translateZ(110px)}.nx-carousel i:nth-child(2){transform:rotateY(120deg) translateZ(110px)}.nx-carousel i:nth-child(3){transform:rotateY(240deg) translateZ(110px)}@keyframes nx-car{0%,20%{transform:rotateY(0)}35%,55%{transform:rotateY(-120deg)}70%,90%{transform:rotateY(-240deg)}100%{transform:rotateY(-360deg)}}`,['window','carousel','3d','spatial'])
add('Spatial Windows','Focus Window','The focused panel sharpens while surrounding layers blur.',`<div class="nx-focus-win"><i></i><main>FOCUS</main><b></b></div>`,`.nx-focus-win{position:relative;width:235px;height:150px}.nx-focus-win i,.nx-focus-win b,.nx-focus-win main{position:absolute;inset:18px;border-radius:18px;background:#171b23;border:1px solid #ffffff18;transition:.4s}.nx-focus-win i{transform:translate(-25px,12px) scale(.94);filter:blur(4px);opacity:.45}.nx-focus-win b{transform:translate(25px,-12px) scale(.94);filter:blur(4px);opacity:.45}.nx-focus-win main{display:grid;place-items:center;color:#fff;font:1000 14px Inter;box-shadow:0 20px 35px #0008}.nx-focus-win:hover main{transform:translateZ(30px) scale(1.06);box-shadow:0 0 35px #756cff33}.nx-focus-win:hover i,.nx-focus-win:hover b{filter:blur(8px);opacity:.2}`,['window','focus','blur','depth'])
add('Spatial Windows','Minimize Fold','A panel folds down into a tiny dock pill.',`<label class="nx-fold"><input type="checkbox"><span>SPATIAL PANEL</span></label>`,`.nx-fold{display:block;width:240px;height:145px;perspective:700px;cursor:pointer}.nx-fold input{position:absolute;opacity:0}.nx-fold span{display:grid;place-items:center;width:100%;height:100%;border-radius:22px;background:linear-gradient(145deg,#1a1f28,#0d1016);border:1px solid #ffffff18;color:#fff;font:900 11px Inter;letter-spacing:.12em;box-shadow:0 22px 40px #0008;transform-origin:bottom;transition:.65s cubic-bezier(.2,.8,.2,1)}.nx-fold input:checked+span{height:36px;transform:translateY(105px) rotateX(78deg) scaleX(.6);border-radius:999px;background:#756cff}`,['window','fold','minimize','3d'])

