add('Physics Toys','Rubber Band','A glowing band stretches toward the pointer.',`<div class="nx-rubber"><i></i><b></b></div>`,`.nx-rubber{position:relative;width:220px;height:130px}.nx-rubber i,.nx-rubber b{position:absolute;width:18px;height:18px;border-radius:50%;background:#2dd4bf;box-shadow:0 0 14px #2dd4bf;top:56px}.nx-rubber i{left:20px}.nx-rubber b{right:20px}.nx-rubber:after{content:"";position:absolute;left:37px;right:37px;top:64px;height:4px;border-radius:4px;background:#2dd4bf;box-shadow:0 0 12px #2dd4bf;transform-origin:left;transform:scaleX(var(--sx,1)) rotate(var(--r,0deg));transition:.06s}`,['physics','rubber','stretch','pointer'],`const p=document.querySelector('.nx-rubber');p.addEventListener('pointermove',e=>{const r=p.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,dx=x-37,dy=y-64,len=Math.min(165,Math.hypot(dx,dy)),ang=Math.atan2(dy,dx)*57.3;p.style.setProperty('--sx',String(len/146));p.style.setProperty('--r',ang+'deg')})`)
