add('Animated Illustrations','Neon Fish','A neon fish swims in a tiny glass tank.',`<div class="nx-fish"><span>◀</span><i></i><i></i></div>`,`.nx-fish{position:relative;width:220px;height:130px;border:1px solid #22d3ee33;border-radius:22px;background:linear-gradient(#07141a,#041017);overflow:hidden;box-shadow:inset 0 0 30px #22d3ee12}.nx-fish span{position:absolute;color:#22d3ee;font-size:42px;filter:drop-shadow(0 0 12px #22d3ee);animation:nx-fish 5s ease-in-out infinite;top:43px}.nx-fish i{position:absolute;width:7px;height:7px;border:1px solid #67e8f9;border-radius:50%;bottom:-8px;animation:nx-bubbles 3s linear infinite;left:35px}.nx-fish i:nth-of-type(2){left:170px;animation-delay:1.2s}@keyframes nx-fish{0%,100%{left:-35px;transform:scaleX(1)}45%{left:180px;transform:scaleX(1)}50%{left:180px;transform:scaleX(-1)}95%{left:-35px;transform:scaleX(-1)}}@keyframes nx-bubbles{to{transform:translateY(-150px);opacity:0}}`,['illustration','fish','neon','swim'])
add('Animated Illustrations','Tiny UFO','A small UFO hovers and beams light downward.',`<div class="nx-ufo"><span></span><i></i></div>`,`.nx-ufo{position:relative;width:180px;height:150px;animation:nx-ufo-f 3s ease-in-out infinite}.nx-ufo span{position:absolute;left:43px;top:35px;width:94px;height:32px;border-radius:50%;background:linear-gradient(#8b95a4,#303640);box-shadow:inset 0 3px #fff3,0 8px 18px #0007}.nx-ufo span:before{content:"";position:absolute;left:27px;top:-22px;width:40px;height:28px;border-radius:50% 50% 20% 20%;background:#67e8f944;border:1px solid #67e8f988}.nx-ufo i{position:absolute;left:62px;top:64px;width:56px;height:74px;clip-path:polygon(30% 0,70% 0,100% 100%,0 100%);background:linear-gradient(#67e8f955,transparent);animation:nx-beam 1.8s ease-in-out infinite}@keyframes nx-ufo-f{50%{transform:translateY(-10px) rotate(3deg)}}@keyframes nx-beam{50%{opacity:.25;transform:scaleX(1.25)}}`,['illustration','ufo','hover','beam'])
add('Animated Illustrations','Campfire','A stylized little fire flickers over glowing logs.',`<div class="nx-fire"><i></i><i></i><b></b><span></span></div>`,`.nx-fire{position:relative;width:150px;height:140px}.nx-fire i{position:absolute;left:62px;top:34px;width:28px;height:70px;border-radius:50% 50% 40% 40%;background:linear-gradient(#fde68a,#fb923c 45%,#ef4444);filter:drop-shadow(0 0 18px #fb923c);transform-origin:bottom;animation:nx-flame 1s ease-in-out infinite}.nx-fire i:nth-child(2){left:77px;top:55px;width:18px;height:48px;background:linear-gradient(#fff,#facc15,#fb923c);animation-delay:.15s}.nx-fire b,.nx-fire span{position:absolute;width:75px;height:13px;border-radius:10px;background:#7c2d12;bottom:23px;left:38px;transform:rotate(20deg);box-shadow:0 6px 10px #0005}.nx-fire span{transform:rotate(-20deg)}@keyframes nx-flame{0%,100%{transform:scaleX(.9) rotate(-3deg)}50%{transform:scaleX(1.12) rotate(4deg) translateY(-5px)}}`,['illustration','fire','flicker','ambient'])
add('Animated Illustrations','Flying Paper','A paper plane loops gently through space.',`<div class="nx-paper"><span>➤</span></div>`,`.nx-paper{position:relative;width:220px;height:135px;border-radius:20px;background:radial-gradient(circle at 50% 100%,#756cff18,transparent 55%);overflow:hidden}.nx-paper span{position:absolute;color:#e2e8f0;font-size:34px;filter:drop-shadow(0 6px 6px #0006);offset-path:path('M -20 90 C 35 10 165 10 210 70 C 155 125 70 135 -20 90');animation:nx-paper 6s linear infinite}@keyframes nx-paper{to{offset-distance:100%;rotate:360deg}}`,['illustration','paper','plane','loop'])
add('Animated Illustrations','Pixel Pet','A tiny pixel creature idles, blinks and hops.',`<div class="nx-pet"><i></i><b></b><span></span></div>`,`.nx-pet{position:relative;width:120px;height:110px;image-rendering:pixelated;animation:nx-pet-hop 2.8s steps(1) infinite}.nx-pet:before{content:"";position:absolute;left:25px;top:28px;width:70px;height:58px;background:#8b5cf6;box-shadow:0 -12px 0 -5px #8b5cf6,0 12px 0 -5px #5b21b6}.nx-pet i,.nx-pet b{position:absolute;top:49px;width:8px;height:8px;background:#fff;z-index:2;animation:nx-pet-blink 4s steps(1) infinite}.nx-pet i{left:43px}.nx-pet b{right:43px}.nx-pet span{position:absolute;left:51px;top:69px;width:18px;height:5px;background:#3b0764;z-index:2}@keyframes nx-pet-hop{0%,70%,100%{transform:translateY(0)}75%{transform:translateY(-15px)}80%{transform:translateY(0)}}@keyframes nx-pet-blink{0%,48%,54%,100%{transform:scaleY(1)}50%,52%{transform:scaleY(.1)}}`,['illustration','pixel','pet','character'])
add('Animated Illustrations','Rocket Scene','A rocket floats above a pulsing planetary horizon.',`<div class="nx-scene"><i>🚀</i><span></span></div>`,`.nx-scene{position:relative;width:220px;height:150px;overflow:hidden;border-radius:22px;background:radial-gradient(circle at 50% 100%,#312e81 0 26%,#0f172a 27% 50%,#020617 75%)}.nx-scene:before{content:"";position:absolute;inset:0;background:radial-gradient(circle,#fff 0 1px,transparent 1.5px) 0 0/28px 28px;opacity:.5}.nx-scene i{position:absolute;font-style:normal;font-size:38px;left:91px;top:44px;animation:nx-rocket-scene 3s ease-in-out infinite;z-index:2}.nx-scene span{position:absolute;width:26px;height:55px;left:98px;top:80px;background:linear-gradient(#facc15aa,#f97316aa,transparent);filter:blur(4px);clip-path:polygon(35% 0,65% 0,100% 100%,0 100%);animation:nx-flare 1s ease-in-out infinite}@keyframes nx-rocket-scene{50%{transform:translateY(-15px) rotate(4deg)}}@keyframes nx-flare{50%{transform:scaleY(.7);opacity:.6}}`,['illustration','rocket','space','scene'])
add('Animated Illustrations','Rain Window','Raindrops slide down a blurred night window.',`<div class="nx-rain">${Array.from({length:12},(_,i)=>`<i style="--x:${8+i*7}%;--d:${(i%5)*.2}s"></i>`).join('')}</div>`,`.nx-rain{position:relative;width:220px;height:145px;border:1px solid #ffffff22;border-radius:20px;background:linear-gradient(#0f172aaa,#020617dd),radial-gradient(circle at 70% 25%,#38bdf844,transparent 35%);backdrop-filter:blur(8px);overflow:hidden;box-shadow:inset 0 0 30px #0008}.nx-rain i{position:absolute;left:var(--x);top:-20px;width:2px;height:24px;border-radius:2px;background:linear-gradient(transparent,#bae6fd);animation:nx-rain 1.8s linear infinite;animation-delay:var(--d)}@keyframes nx-rain{to{transform:translateY(185px)}}`,['illustration','rain','glass','ambient'])

